export interface UsageMetadata {
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
}

/** One turn's provider-call usage: every round's report summed, `undefined` when no round reported. */
export type TurnUsage = UsageMetadata;

export interface AIProviderResponse {
  usage?: UsageMetadata;
}

export interface AIProvider {
---

export function extractStopReason(chunk: MessageChunk): string | null {
  return chunk.type === 'stop' ? chunk.stopReason : null;
}

export function extractUsage(chunk: MessageChunk): UsageMetadata | undefined {
  return chunk.type === 'stop' ? chunk.usage : undefined;
}

// Only reported rounds are added, so a silent round neither zeroes the total nor turns it into NaN.
export function addRoundUsage(
  turn: UsageMetadata | undefined,
  round: UsageMetadata | undefined
): UsageMetadata | undefined {
  if (round === undefined) return turn;
  if (turn === undefined) return round;
  return {
    inputTokens: turn.inputTokens + round.inputTokens,
    outputTokens: turn.outputTokens + round.outputTokens,
    totalTokens: turn.totalTokens + round.totalTokens,
  };
}

